def get_db():
    import psycopg2, psycopg2.extras, os, sys
    sys.path.insert(0, os.path.expanduser("~/Downloads/anish_app_v2"))
    try:
        import config
        url = config.DATABASE_URL
    except Exception:
        url = os.environ.get("DATABASE_URL")
    return psycopg2.connect(url, cursor_factory=psycopg2.extras.RealDictCursor)


def add_questions():
    conn = get_db()
    cur = conn.cursor()
    total_added = 0

    for topic_title, questions in EXTRA_QUESTIONS.items():
        cur.execute("SELECT id FROM topics WHERE title = %s", (topic_title,))
        row = cur.fetchone()
        if not row:
            print(f"WARNING: Topic not found: {topic_title}")
            continue
        topic_id = row["id"]
        cur.execute("SELECT question_text FROM questions WHERE topic_id = %s", (topic_id,))
        existing = {r["question_text"] for r in cur.fetchall()}
        added = 0
        for q in questions:
            q_text, q_type, a, b, c, d, answer, explanation, level = q
            if q_text in existing:
                continue
            cur.execute("""
                INSERT INTO questions (topic_id, question_text, question_type,
                    option_a, option_b, option_c, option_d,
                    correct_answer, explanation, difficulty)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            """, (topic_id, q_text, q_type, a, b, c, d, answer, explanation, level))
            added += 1
        conn.commit()
        print(f"  {topic_title}: +{added} questions")
        total_added += added

    cur.close()
    conn.close()
    print(f"\nTotal added: {total_added} questions")


if __name__ == "__main__":
    add_questions()
